"""Notifications are generated by real events, delivered only to the
people who should get them, and only reachable by their recipient."""
from datetime import datetime, timedelta, timezone

from fastapi import status


def _invite(client, owner, member):
    resp = client.post(f"/api/v1/workspaces/{owner['workspace_id']}/invite", headers=owner["headers"],
                       json={"email": member["email"], "role": "member"})
    assert resp.status_code == status.HTTP_200_OK, resp.text


def _notifications(client, user, workspace_id):
    resp = client.get(f"/api/v1/workspaces/{workspace_id}/notifications/", headers=user["headers"])
    assert resp.status_code == status.HTTP_200_OK, resp.text
    return resp.json()


def _create_task(client, user, ws, **body):
    resp = client.post(f"/api/v1/workspaces/{ws}/tasks", headers=user["headers"], json={"title": "Fix login", "task_type": "task", **body})
    assert resp.status_code == status.HTTP_201_CREATED, resp.text
    return resp.json()


def test_assignment_status_and_comment_notify_the_right_people(client, signed_up_user, other_user):
    owner, member = signed_up_user, other_user
    ws = owner["workspace_id"]
    _invite(client, owner, member)

    task = _create_task(client, owner, ws, assignee_id=member["user_id"])
    member_notes = _notifications(client, member, ws)
    assert [n["type"] for n in member_notes] == ["assigned"]
    assert task["ticket_key"] in member_notes[0]["title"]
    assert _notifications(client, owner, ws) == []  # never notified about your own action

    # Member moves it: the owner (creator) hears about it, the member doesn't.
    client.put(f"/api/v1/workspaces/{ws}/tasks/{task['task_id']}", headers=member["headers"], json={"status": "in_progress"})
    owner_notes = _notifications(client, owner, ws)
    assert [n["type"] for n in owner_notes] == ["status_changed"]
    assert "In Progress" in owner_notes[0]["title"]
    assert len(_notifications(client, member, ws)) == 1

    # Owner comments: member (assignee) is notified; HTML is stripped.
    resp = client.post(f"/api/v1/workspaces/{ws}/comments/", headers=owner["headers"],
                       json={"task_id": task["task_id"], "content": "<p>Can you <b>check</b> this?</p>"})
    assert resp.status_code == status.HTTP_201_CREATED, resp.text
    notes = _notifications(client, member, ws)
    latest = notes[0]
    assert latest["type"] == "comment"
    assert latest["message"] == "Can you check this?"


def test_commenter_becomes_a_watcher(client, signed_up_user, other_user):
    owner, member = signed_up_user, other_user
    ws = owner["workspace_id"]
    _invite(client, owner, member)
    task = _create_task(client, owner, ws)

    client.post(f"/api/v1/workspaces/{ws}/comments/", headers=member["headers"], json={"task_id": task["task_id"], "content": "+1"})
    got = client.get(f"/api/v1/workspaces/{ws}/tasks/{task['task_id']}", headers=owner["headers"]).json()
    assert member["user_id"] in got["watchers"]

    # ...so a later status change by the owner reaches them.
    client.put(f"/api/v1/workspaces/{ws}/tasks/{task['task_id']}", headers=owner["headers"], json={"status": "done"})
    assert "status_changed" in [n["type"] for n in _notifications(client, member, ws)]


def test_disabled_notification_type_is_respected(client, signed_up_user, other_user):
    owner, member = signed_up_user, other_user
    ws = owner["workspace_id"]
    _invite(client, owner, member)
    settings = client.get(f"/api/v1/workspaces/{ws}/settings/", headers=member["headers"])
    assert settings.status_code == status.HTTP_200_OK, settings.text
    resp = client.put(f"/api/v1/workspaces/{ws}/settings/{settings.json()['settings_id']}/notifications",
                      headers=member["headers"], json={"assigned": False})
    assert resp.status_code == status.HTTP_200_OK, resp.text

    _create_task(client, owner, ws, assignee_id=member["user_id"])
    assert _notifications(client, member, ws) == []


def test_due_reminder_fires_once_and_repeating_one_rolls_forward(client, signed_up_user):
    ws, h = signed_up_user["workspace_id"], signed_up_user["headers"]
    past = (datetime.now(timezone.utc) - timedelta(minutes=5)).isoformat()
    future = (datetime.now(timezone.utc) + timedelta(days=1)).isoformat()
    base = f"/api/v1/workspaces/{ws}/reminders/"
    client.post(base, headers=h, json={"title": "Pay invoice", "due_date": past})
    client.post(base, headers=h, json={"title": "Standup", "due_date": past, "repeat": "daily"})
    client.post(base, headers=h, json={"title": "Not yet", "due_date": future})

    first = _notifications(client, signed_up_user, ws)
    assert sorted(n["title"] for n in first) == ["Reminder: Pay invoice", "Reminder: Standup"]
    assert len(_notifications(client, signed_up_user, ws)) == 2  # no duplicates on the next poll

    reminders = {r["title"]: r for r in client.get(base, headers=h).json()}
    rolled = datetime.fromisoformat(reminders["Standup"]["due_date"].replace("Z", "+00:00"))
    if rolled.tzinfo is None:
        rolled = rolled.replace(tzinfo=timezone.utc)
    assert rolled > datetime.now(timezone.utc)


def test_notifications_and_comments_are_private_to_their_owner(client, signed_up_user, other_user):
    owner, member = signed_up_user, other_user
    ws = owner["workspace_id"]
    _invite(client, owner, member)
    task = _create_task(client, owner, ws, assignee_id=member["user_id"])
    note_id = _notifications(client, member, ws)[0]["notification_id"]

    # The owner (same workspace) can't read or mark the member's notification.
    assert client.get(f"/api/v1/workspaces/{ws}/notifications/{note_id}", headers=owner["headers"]).status_code == status.HTTP_404_NOT_FOUND
    assert client.put(f"/api/v1/workspaces/{ws}/notifications/{note_id}", headers=owner["headers"], json={"is_read": True}).status_code == status.HTTP_404_NOT_FOUND

    # Mark-all-read only touches the caller's own.
    assert client.post(f"/api/v1/workspaces/{ws}/notifications/read-all", headers=member["headers"]).json() == {"updated": 1}
    assert all(n["is_read"] for n in _notifications(client, member, ws))

    comment = client.post(f"/api/v1/workspaces/{ws}/comments/", headers=owner["headers"], json={"task_id": task["task_id"], "content": "mine"}).json()
    assert client.put(f"/api/v1/workspaces/{ws}/comments/{comment['comment_id']}", headers=member["headers"], json={"content": "edited"}).status_code == status.HTTP_403_FORBIDDEN
    assert client.delete(f"/api/v1/workspaces/{ws}/comments/{comment['comment_id']}", headers=member["headers"]).status_code == status.HTTP_403_FORBIDDEN


def test_cannot_comment_on_another_workspaces_task(client, signed_up_user, other_user):
    task = _create_task(client, signed_up_user, signed_up_user["workspace_id"])
    resp = client.post(f"/api/v1/workspaces/{other_user['workspace_id']}/comments/", headers=other_user["headers"],
                       json={"task_id": task["task_id"], "content": "sneaky"})
    assert resp.status_code == status.HTTP_404_NOT_FOUND


def test_unassign_with_empty_string(client, signed_up_user, other_user):
    ws = signed_up_user["workspace_id"]
    _invite(client, signed_up_user, other_user)
    task = _create_task(client, signed_up_user, ws, assignee_id=other_user["user_id"])
    resp = client.put(f"/api/v1/workspaces/{ws}/tasks/{task['task_id']}", headers=signed_up_user["headers"], json={"assignee_id": ""})
    assert resp.status_code == status.HTTP_200_OK, resp.text
    assert resp.json()["assignee_id"] is None
